16	// ============================================================================
17	// CUDA sm_90 launch glue for SuperGrok v1.1.
18	// Algorithm: csrc/algorithms/supergrok11.h
19	//
20	// Two-sweep cooperative pattern:
21	//   Sweep A: meta-net forward + cosine gate reduction
22	//   Sweep B: smart_grad mixing + Adam apply (uses gate from sweep A)
23	//
24	// The meta-net hidden width H is fixed at compile time. Defaults to 32
25	// (matches the canonical SharpnessMetaNet hidden_dim in
26	// grokking_optimizers/optimizers/supergrok11.py).
