56	constexpr int SG11_H = 32;
57	
58	// Minimum resident blocks/SM for the element-wise sweeps. Caps registers so
59	// occupancy stays high on the (memory-bound) Adam apply.
60	#ifndef SG_SUPERGROK11_MIN_BLOCKS
61	#define SG_SUPERGROK11_MIN_BLOCKS 4
62	#endif
