64	// Cooperatively stage the per-element meta-net phi weights into shared memory
65	// ONCE per block, then hand the shared pointers to the canonical
66	// sg11_phi_forward<H>. W1 is [H,2] (row-major, 2 inputs/hidden unit), b1/W2 are
67	// [H]. The same weights are read by every element this block processes; staging
68	// removes the per-element re-read from GLOBAL inside the H-wide forward loop. NO
69	// math/signature change — the fn still takes const float* (single-sourced in
70	// algorithms/supergrok11.h).
71	template <int H>
72	__device__ __forceinline__ void sg11_stage_phi_weights(
73	    const float* __restrict__ W1, const float* __restrict__ b1,
74	    const float* __restrict__ W2,
75	    float* sW1, float* sb1, float* sW2
76	) {
77	    for (int j = threadIdx.x; j < H * 2; j += blockDim.x) sW1[j] = W1[j];
78	    for (int j = threadIdx.x; j < H;     j += blockDim.x) { sb1[j] = b1[j]; sW2[j] = W2[j]; }
79	    __syncthreads();
80	}
