82	template <typename GradT>
83	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_SUPERGROK11_MIN_BLOCKS)
84	sg11_sweep_a_kernel(
85	    float* mu_out, const GradT* grad, const float* sharpness, const float* momentum,
86	    const float* W1, const float* b1, const float* W2, float b2,
87	    float* gate_num_p, float* gate_den_g_p, float* gate_den_m_p,
88	    int64_t N
89	) {
90	    __shared__ float sW1[SG11_H * 2];
91	    __shared__ float sb1[SG11_H];
92	    __shared__ float sW2[SG11_H];
93	    sg11_stage_phi_weights<SG11_H>(W1, b1, W2, sW1, sb1, sW2);
94	
95	    float gn = 0.0f, gdg = 0.0f, gdm = 0.0f;
96	    const int64_t stride = prim::grid_stride();
97	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
98	        SG_SANITIZE_GRAD_INPLACE(grad, i);
99	        const float g = static_cast<float>(grad[i]);
100	        const float s = sharpness[i];
101	        const float mu_val = sg11_phi_forward<SG11_H>(g, s, sW1, sb1, sW2, b2);
102	        sg11_sweep_a_step(mu_out, grad, sharpness, momentum, mu_val, i,
103	                          gn, gdg, gdm);
104	    }
105	    float r1 = prim::block_reduce_sum_f32(gn);
106	    float r2 = prim::block_reduce_sum_f32(gdg);
107	    float r3 = prim::block_reduce_sum_f32(gdm);
108	    if (threadIdx.x == 0) {
109	        atomicAdd(gate_num_p, r1);
110	        atomicAdd(gate_den_g_p, r2);
111	        atomicAdd(gate_den_m_p, r3);
112	    }
113	}
