138	// FP32 vec4 sweep B: float4 traffic on param/state/grad/mu, canonical
139	// sg11_sweep_b_step CALLED 4× on the register lanes. Math is NOT re-typed here.
140	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_SUPERGROK11_MIN_BLOCKS)
141	sg11_sweep_b_kernel_vec4_fp32(
142	    float4* param4, float4* exp_avg4, float4* exp_avg_sq4,
143	    const float4* grad4, const float4* mu4, float gate,
144	    float alpha, float lr, float beta1, float beta2, float eps, float wd,
145	    float bc1, float bc2, int64_t N4
146	) {
147	    const int64_t stride = prim::grid_stride();
148	    for (int64_t i = prim::grid_stride_index(); i < N4; i += stride) {
149	        float4 p  = prim::ld_f32v4(param4 + i);
150	        float4 m  = prim::ld_f32v4(exp_avg4 + i);
151	        float4 v  = prim::ld_f32v4(exp_avg_sq4 + i);
152	        float4 g  = prim::ldg_f32v4(grad4 + i);
153	        float4 mu = prim::ldg_f32v4(mu4 + i);
154	        ::grokking::sm90::sg_sanitize_grad4(g);
155	        #pragma unroll
156	        for (int u = 0; u < 4; ++u) {
157	            sg11_sweep_b_step(&p.x, &m.x, &v.x, &g.x, &mu.x, gate,
158	                              alpha, lr, beta1, beta2, eps, wd, bc1, bc2, u);
159	        }
160	        prim::st_f32v4(param4 + i, p);
161	        prim::st_f32v4(exp_avg4 + i, m);
162	        prim::st_f32v4(exp_avg_sq4 + i, v);
163	    }
164	}
