299	    const int block = SG_TUNED_BLOCK_SIZE;
300	    const int grid = static_cast<int>(
301	        std::min<int64_t>(65535, (N + block - 1) / block));
302	    float b2_val = b2.item<float>();
303	
304	    AT_DISPATCH_FLOATING_TYPES_AND2(
