356	// SAM perturbation: param += rho_over_norm * grad
357	template <typename ParamT>
358	__global__ void sg11_sam_perturb_kernel(
359	    ParamT* param, const ParamT* grad, float rho_over_norm, int64_t N
360	) {
361	    const int64_t stride = prim::grid_stride();
362	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
363	        float p = static_cast<float>(param[i]);
364	        float g = ::grokking::sm90::sg_sanitize_grad(static_cast<float>(grad[i]));
365	        param[i] = static_cast<ParamT>(p + rho_over_norm * g);
366	    }
367	}
