388	// Sharpness restore: param = backup, sharpness = ||sam_grad - normal_grad||
389	template <typename ParamT>
390	__global__ void sg11_sharpness_restore_kernel(
391	    ParamT* param, float* sharpness, const ParamT* backup,
392	    const ParamT* sam_grad, const ParamT* normal_grad, int64_t N
393	) {
394	    const int64_t stride = prim::grid_stride();
395	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
396	        param[i] = backup[i];
397	        float sg = static_cast<float>(sam_grad[i]);
398	        float ng = static_cast<float>(normal_grad[i]);
399	        float diff = sg - ng;
400	        sharpness[i] = diff * diff;
401	    }
402	}
