428	// Cosine gate: cos_sim(smart_grad, mu) clamped to [0,1].
429	float compute_cosine_gate_fused(
430	    torch::Tensor smart_grad, torch::Tensor mu, float gate_temp
431	) {
432	    auto sg_f = smart_grad.to(torch::kFloat32).flatten();
433	    auto mu_f = mu.to(torch::kFloat32).flatten();
434	    float num = (sg_f * mu_f).sum().item<float>();
435	    float den_g = (sg_f * sg_f).sum().item<float>();
436	    float den_m = (mu_f * mu_f).sum().item<float>();
437	    float denom = sqrtf(den_g * den_m + 1e-12f);
438	    float gate = (denom > 0.0f) ? (num / denom) : 0.0f;
439	    return fminf(fmaxf(gate, 0.0f), 1.0f);
440	}
